self.addEventListener("push",i=>{if(i.data){let t=i.data.json();i.waitUntil(self.registration.showNotification(t.title,{body:t.body,icon:t.icon||"/icons/icon-192x192.png",badge:t.badge||"/icons/icon-192x192.png",vibrate:[200,100,200],data:{url:t.url||"/"}}))}}),self.addEventListener("notificationclick",i=>{i.notification.close(),i.notification.data&&i.notification.data.url&&i.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(t=>{for(let n of t)if(n.url===i.notification.data.url&&"focus"in n)return n.focus();if(self.clients.openWindow)return self.clients.openWindow(i.notification.data.url)}))});